#include<bits/stdc++.h>
#include<atcoder/segtree>
using namespace std;

using S=int;
S op(S x,S y){return max(x,y);}
S e(){return 0;}

int main(){
	int n;
	cin >> n;
	vector<array<int,2>>rl;
	for(int i=0;i<n;i++){
		int l,r;
		cin >> l >> r;
		l--,r--;
		if(l>r)swap(l,r);
		rl.push_back({r,l});
	}

	sort(rl.begin(),rl.end());
	atcoder::segtree<S,op,e>seg(2*n);

	vector<int>ans(n);
	for(int i=0;i<n;i++){
		auto[r,l]=rl[i];
		ans[i]=seg.prod(l,r)+1;
		seg.set(l,ans[i]);
	}

	for(int i=0;i<n;i++){
		auto[r,l]=rl[i];
		ans[i]+=seg.prod(r,2*n);
	}

	cout << *max_element(ans.begin(),ans.end()) << endl;
}
